def horizontal_partition(
        nodes, triton_scheduling, kernel_map, node_info_map, custom_algorithm=False
    ):
        original_groups = []
        try:
            if custom_algorithm:
                # Community partitioning expects scalar sizes; NPU codegen needs
                # the original per-axis groups after the partition is selected.
                for node in nodes:
                    device, sizes = node.group
                    if any(isinstance(size, NumelList) for size in sizes):
                        original_groups.append((node, node.group))
                        node.group = (
                            device,
                            tuple(
                                sympy.sympify(size.numels())
                                if isinstance(size, NumelList)
                                else size
                                for size in sizes
                            ),
                        )
            partitions = ComboKernel.horizontal_partition(
                nodes, triton_scheduling, node_info_map, custom_algorithm
            )
        finally:
            for node, group in original_groups:
                node.group = group
        compatible_partitions = []
        for partition in partitions:
            groups = {}
            for node in partition:
                kernel = kernel_map[node]
                # One launcher/autotuner supplies block arguments for the whole
                # combo. Only combine kernels with the same block ABI and mode.
                key = (
                    kernel.npu_kernel_type,
                    kernel.inside_reduction,
                    kernel.persistent_reduction,
                    tuple(
                        (
                            axis.name, axis.is_split_axis, axis.is_tiling_axis,
                            axis.is_no_loop_axis, axis.is_reduction,
                        )
                        for axis in kernel.sorted_axis
                    ),
                )
                groups.setdefault(key, []).append(node)
            compatible_partitions.extend(groups.values())
        return compatible_partitions

def select_combo_heuristics(
        self, heuristics_list: list[str], size_hints_list: list[dict[str, int]]
    ) -> tuple[str, dict[str, int], TritonKernel]:
        # This shape only describes the shared search envelope. Preserve every
        # subkernel's actual shape separately for grid and resource calculations.
        size_hints = {}
        split_names = {axis.name for axis in self.sub_kernels[0].split_axis}
        for subkernel_hints in size_hints_list:
            for axis_name, extent in subkernel_hints.items():
                if axis_name in split_names:
                    size_hints[axis_name] = size_hints.get(axis_name, 0) + extent
                else:
                    size_hints[axis_name] = max(size_hints.get(axis_name, 1), extent)
        if not self.enable_autotune:
            return "foreach", size_hints, self.sub_kernels[0]
        return heuristics_list[0], size_hints, self.sub_kernels[0]

def _triton_config_npu_index_combo(size_hints, inductor_meta, triton_meta):
    """Generate candidates for one launch containing all combo subkernels."""
    subkernels = inductor_meta["combo_subkernel_meta"]
    axis_names = inductor_meta["axis_names"]
    input_signature = (triton_meta or {}).get("signature", {})
    input_ptr_num = sum("ptr" in name for name in input_signature)
    kernel_type = NPUKernelType(inductor_meta.get("npu_kernel_type", "simd"))
    generator = ComboTileGenerator(
        subkernels,
        input_ptr_num=input_ptr_num,
        npu_kernel_type=kernel_type,
    )
    if kernel_type == NPUKernelType.SIMD_SIMT_MIX:
        configs = []
        for mode in (NPUKernelType.SIMT_ONLY, NPUKernelType.SIMT_TEMPLATE):
            generator.set_kernel_type(mode)
            configs.extend(generator.descend_split_tiling())
    else:
        configs = generator.descend_split_tiling()
    if not configs:
        raise RuntimeError("No legal shared tiling for the complete combo kernel")

    for candidate in configs:
        candidate.kwargs["split_axis"] = tuple(generator.split_axis)
        candidate.kwargs["split_blocks"] = tuple(
            candidate.kwargs[f"{axis_names[axis].upper()}BLOCK"]
            for axis in generator.split_axis
        )
    logging.debug(
        "[%s], combo candidate tiling count: [%s]",
        inductor_meta["kernel_name"], len(configs),
    )
    return brutal_prune_tiling_configs_if_fast_run(configs, inductor_meta)

def autotune_to_one_config(self, *args, **kwargs):
        """Do the actual autotuning"""
        start_time = time.time_ns()
        if self.candidate_plan is None:
            self.candidate_plan = build_candidate_plan(
                self.configs, self.runtime_block_arg_names
            )
        timings = self._benchmark_candidate_entries(*args, **kwargs)
        benchmark_time_taken_ns = time.time_ns() - start_time
        candidate_map = {
            candidate["candidate_id"]: candidate
            for candidate in self.candidate_plan["candidate_entries"]
        }
        best_candidate_id, _ = builtins.min(
            timings.items(), key=lambda item: item[1]
        )
        best_candidate = candidate_map[best_candidate_id]
        if not self.variant_launcher_map:
            self._refresh_variant_launchers()
        best_launcher = self.variant_launcher_map[best_candidate["variant_id"]]
        self._set_best_candidate(best_candidate, best_launcher)
        self.launchers = [best_launcher]
        self.autotune_time_taken_ns = (
            self.precompile_time_taken_ns + benchmark_time_taken_ns
        )
        if self.save_cache_hook:
            best_config = (
                self.best_candidate_config
                if self.best_candidate_config is not None
                else self.launchers[0].config
            )
            self.save_cache_hook(
                best_config,
                self.autotune_time_taken_ns,
                found_by_coordesc=self.inductor_meta.get(
                    "coordinate_descent_tuning", False
                ),
                triton_cache_hash=getattr(self.launchers[0], "cache_hash", None)
            )
